// Generated from the WHATWG `shift_jis` decoder (JIS X 0208 rows only; CP932
// NEC row 13 excluded). Entry `i` is the Unicode code point of the Shift_JIS
// character whose QR Kanji value is `i` (0 = unassigned), zigzag-delta encoded
// as unsigned LEB128 varints and packed as base64. Do not edit by hand.

/** Number of QR Kanji values described by {@link QR_CODE_KANJI_TABLE}. */
export const QR_CODE_KANJI_TABLE_LENGTH = 7973;

/** Packed QR Kanji value -> Unicode table. */
export const QR_CODE_KANJI_TABLE =
  "";
